create extension if not exists pgcrypto;
create type public.app_role as enum ('solicitante','agente','directivo','administrador');
create type public.ticket_status as enum ('nuevo','abierto','en_progreso','en_espera','resuelto','cerrado');
create type public.ticket_priority as enum ('baja','media','alta','urgente');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text unique not null,full_name text not null,role public.app_role not null default 'solicitante',campus text);
create table public.app_settings(id int primary key default 1 check(id=1),support_email text not null default 'mesadeayuda@udlondres.com',first_response_hours int not null default 8,resolution_hours int not null default 48);insert into public.app_settings(id) values(1) on conflict do nothing;
create table public.tickets(id uuid primary key default gen_random_uuid(),folio text generated always as('UDL-'||upper(substr(id::text,1,8))) stored,subject text not null check(length(subject) between 5 and 180),description text not null,category text not null default 'Otro',campus text not null check(campus in('Centro','Roma','San Ángel','Coapa','Insurgentes','Reforma','Satélite','Zaragoza')),status public.ticket_status not null default 'nuevo',priority public.ticket_priority not null default 'media',requester_id uuid not null references public.profiles(id),assignee_id uuid references public.profiles(id),created_at timestamptz default now(),updated_at timestamptz default now(),first_response_due_at timestamptz default now()+interval '8 hours',resolution_due_at timestamptz default now()+interval '48 hours',resolved_at timestamptz);
create index tickets_status_idx on public.tickets(status,created_at desc);create index tickets_assignee_idx on public.tickets(assignee_id);
create table public.ticket_comments(id uuid primary key default gen_random_uuid(),ticket_id uuid references public.tickets(id) on delete cascade,author_id uuid references public.profiles(id),body text not null,visibility text default 'public',created_at timestamptz default now());
create table public.ticket_events(id uuid primary key default gen_random_uuid(),ticket_id uuid references public.tickets(id),actor_id uuid references public.profiles(id),event_type text not null,payload jsonb default '{}',created_at timestamptz default now());
create table public.audit_logs(id uuid primary key default gen_random_uuid(),actor_id uuid references public.profiles(id),action text not null,entity_type text,entity_id text,metadata jsonb default '{}',created_at timestamptz default now());
create table public.surveys(id uuid primary key default gen_random_uuid(),ticket_id uuid unique references public.tickets(id),requester_id uuid references public.profiles(id),token uuid default gen_random_uuid(),score int check(score between 1 and 5),comment text,submitted_at timestamptz);
create table public.google_mail_config(id int primary key default 1,mailbox_email text default 'mesadeayuda@udlondres.com',refresh_token text,last_history_id text);insert into public.google_mail_config(id) values(1) on conflict do nothing;
create table public.email_ingest(id uuid primary key default gen_random_uuid(),gmail_message_id text unique not null,gmail_thread_id text,ticket_id uuid references public.tickets(id),from_email text,subject text,body text,processing_status text default 'pendiente');
create table public.push_subscriptions(id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles(id),subscription jsonb);
create table public.attachments(id uuid primary key default gen_random_uuid(),ticket_id uuid references public.tickets(id),uploader_id uuid references public.profiles(id),storage_path text,filename text,mime_type text,size_bytes bigint);
create function public.current_role() returns public.app_role language sql stable security definer set search_path=public as $$select role from public.profiles where id=auth.uid()$$;
create function public.is_staff() returns boolean language sql stable security definer set search_path=public as $$select coalesce(public.current_role() in('agente','directivo','administrador'),false)$$;
alter table public.profiles enable row level security;alter table public.app_settings enable row level security;alter table public.tickets enable row level security;alter table public.ticket_comments enable row level security;alter table public.ticket_events enable row level security;alter table public.audit_logs enable row level security;alter table public.surveys enable row level security;alter table public.google_mail_config enable row level security;alter table public.email_ingest enable row level security;alter table public.push_subscriptions enable row level security;alter table public.attachments enable row level security;
create policy profiles_read on public.profiles for select using(id=auth.uid() or public.is_staff());create policy profiles_admin on public.profiles for all using(public.current_role()='administrador') with check(public.current_role()='administrador');
create policy settings_read on public.app_settings for select using(public.is_staff());create policy settings_update on public.app_settings for update using(public.current_role()='administrador') with check(public.current_role()='administrador');
create policy tickets_read on public.tickets for select using(requester_id=auth.uid() or public.current_role() in('directivo','administrador') or(public.current_role()='agente' and(assignee_id=auth.uid() or assignee_id is null)));
create policy tickets_insert on public.tickets for insert with check(requester_id=auth.uid() and assignee_id is null and status='nuevo');create policy tickets_update on public.tickets for update using(public.is_staff()) with check(public.is_staff());
create policy comments_read on public.ticket_comments for select using(exists(select 1 from public.tickets t where t.id=ticket_id and(t.requester_id=auth.uid() or public.is_staff())) and(visibility='public' or public.is_staff()));create policy comments_insert on public.ticket_comments for insert with check(author_id=auth.uid() and exists(select 1 from public.tickets t where t.id=ticket_id and(t.requester_id=auth.uid() or public.is_staff())) and (visibility='public' or public.is_staff()));
create policy event_staff_read on public.ticket_events for select using(public.is_staff());create policy audit_admin on public.audit_logs for all using(public.current_role()='administrador') with check(public.current_role()='administrador');
create policy survey_read on public.surveys for select using(requester_id=auth.uid() or public.is_staff());create policy survey_insert on public.surveys for insert with check(requester_id=auth.uid());
create policy google_admin on public.google_mail_config for all using(public.current_role()='administrador') with check(public.current_role()='administrador');create policy ingest_admin on public.email_ingest for select using(public.current_role()='administrador');create policy push_self on public.push_subscriptions for all using(user_id=auth.uid()) with check(user_id=auth.uid());create policy attachments_staff on public.attachments for select using(public.is_staff());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('ticket-files','ticket-files',false,10485760,array['image/png','image/jpeg','application/pdf','text/plain']) on conflict(id) do nothing;

create policy ticket_files_scoped_read on storage.objects for select using(bucket_id='ticket-files' and exists(select 1 from public.tickets t where t.id::text=(storage.foldername(name))[1] and(t.requester_id=auth.uid() or public.is_staff())));
create policy ticket_files_scoped_upload on storage.objects for insert with check(bucket_id='ticket-files' and exists(select 1 from public.tickets t where t.id::text=(storage.foldername(name))[1] and(t.requester_id=auth.uid() or public.is_staff())));
